import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { loadConfig } from '../src/config.js';
import { connect, dbUrl } from '../src/db.js';
import { mailFrom, send } from '../src/mailer.js';
import { describe, port } from '../src/server.js';
test('defaults', () => assert.deepEqual(loadConfig({}), { dbUrl: 'sqlite://local.db', mailFrom: 'noreply@example.com', port: 3000 }));
test('overrides', () => assert.deepEqual(loadConfig({ APP_DB_URL: 'pg://x', APP_MAIL_FROM: 'a@b.c', APP_PORT: '81' }), { dbUrl: 'pg://x', mailFrom: 'a@b.c', port: 81 }));
test('modules still work', () => {
  process.env.APP_PORT = '4000';
  process.env.APP_DB_URL = 'pg://live';
  assert.equal(port(), 4000);
  assert.equal(describe(), 'listening on 4000');
  assert.equal(dbUrl(), 'pg://live');
  assert.equal(connect().url, 'pg://live');
  assert.equal(mailFrom(), 'noreply@example.com');
  assert.equal(send('x@y.z', 'hi').from, 'noreply@example.com');
});
test('modules use config.js and not process.env', () => {
  for (const f of ['db', 'mailer', 'server']) {
    const src = readFileSync(new URL('../src/' + f + '.js', import.meta.url), 'utf8');
    assert.ok(src.includes('config.js'), f + '.js does not import config.js');
    assert.ok(!src.includes('process.env'), f + '.js still reads process.env');
  }
});

solution.src/config.js:
export function loadConfig(env = process.env) {
  return {
    dbUrl: env.APP_DB_URL ?? 'sqlite://local.db',
    mailFrom: env.APP_MAIL_FROM ?? 'noreply@example.com',
    port: Number(env.APP_PORT ?? 3000),
  };
}

